/* ═══════════ API / DATABASE ═══════════ */
const isLocalHttpFrontend = window.location.protocol === 'http:' && ['5500','5501','5502'].includes(window.location.port);
// Never send a mixed-content request from an HTTPS preview to http://localhost.
// Relative API URLs work with the Node server and with HTTPS preview proxies.
const API_BASE=isLocalHttpFrontend ? 'http://localhost:5001' : '';
let AUTH_TOKEN=localStorage.getItem('hf_token')||'';
let DASHBOARD_STATE={enrollments:[],posts:[],unreadMessages:0};
let categoriesPromise=null;
let categoriesCache=[];
let coursesPromise=null;
let adminUsersPromise=null;

function buildApiUrl(path){
  if(!path) return API_BASE || '/';
  if(path.startsWith('/api/')) return path;
  const normalizedPath=path.replace(/^\/+/, '');
  if(path.startsWith('/payments')) return `${API_BASE || ''}/api/${normalizedPath}`;
  return `${API_BASE || ''}/api/site/${normalizedPath}`;
}

async function apiRequest(path,{method='GET',body,headers={}}={}){
  const opts={method,headers:{...headers}};
  if(AUTH_TOKEN) opts.headers.Authorization=`Bearer ${AUTH_TOKEN}`;
  if(body!==undefined){
    if(body instanceof FormData){
      opts.body = body;
    } else {
      opts.headers['Content-Type']='application/json';
      opts.body=JSON.stringify(body);
    }
  }

  const url=buildApiUrl(path);
  const res=await fetch(url,opts);
  const data=await res.json().catch(()=>({}));
  if(!res.ok){
    // A database reset can invalidate the locally cached account token.
    if(res.status===401&&data.error==='المستخدم غير موجود'){
      clearSession();
      if(typeof updNav==='function') updNav();
      if(typeof showAuth==='function') showAuth();
    }
    const err=new Error(data.error||'حدث خطأ أثناء الاتصال بالخادم');
    if(data.requireVerify) err.requireVerify=true;
    if(data.userId) err.userId=data.userId;
    throw err;
  }
  return data;
}

function setSession(token,user){
  AUTH_TOKEN=token||'';
  if(AUTH_TOKEN) localStorage.setItem('hf_token',AUTH_TOKEN);
  else localStorage.removeItem('hf_token');
  CU=user||null;
  if(CU) localStorage.setItem('hf_user',JSON.stringify(CU));
  else localStorage.removeItem('hf_user');
}

/* ── تجهيز رابط الفيديو المحمي بالـ Token ── */
function getProtectedVideoUrl(url) {
  if (!url) return '';
  if ((url.startsWith('/api/site/uploads/') || url.startsWith('/uploads/')) && AUTH_TOKEN) {
    const sep = url.includes('?') ? '&' : '?';
    return url + sep + 'token=' + AUTH_TOKEN;
  }
  return url;
}

/* ── إعدادات الدفع عبر Tap Payments ── */
async function loadTapSdk() {
  try {
    const cfg = await apiRequest('/config');
    if (!cfg.tapPublicKey) {
      toast('Tap public key غير مضبط. يرجى التحقق من الإعدادات.', 'err');
      return false;
    }

    const container = document.getElementById('tap-button-container');
    if (!container) return false;
    container.innerHTML = '<button class="btn-primary" style="width:100%;padding:12px" onclick="startTapCheckout()">ادفع الآن عبر Tap Payments</button>';
    return true;
  } catch (err) {
    toast(err.message || 'فشل التحقق من إعدادات Tap Payments', 'err');
    return false;
  }
}

async function initTapPayments() {
  await loadTapSdk();
  await initCliqPayments();
}

async function startTapCheckout() {
  if (!CU) {
    toast('يرجى تسجيل الدخول أولاً لإتمام الدفع', 'err');
    goPage('account');
    showAuth();
    return;
  }
  if (cart.length === 0) {
    toast('السلة فارغة', 'err');
    return;
  }

  try {
    const { charge, orderId } = await apiRequest('/payments/create-tap-charge', {
      method: 'POST',
      body: { courseIds: cart },
    });

    if (charge?.transaction?.url) {
      openTapCheckoutModal(charge.transaction.url);
      return;
    }

    toast(`تم إنشاء طلب الدفع ${orderId}. سيُفعّل الاشتراك بعد تأكيد الدفع.`, 'gold');
  } catch (err) {
    toast(err.message || 'حدث خطأ أثناء الدفع عبر Tap Payments', 'err');
  }
}

function openTapCheckoutModal(url){
  if (!url) return;
  // Payment providers should open in the top-level window instead of a third-party iframe.
  window.location.assign(url);
}

function closeTapCheckoutModal(){
  const modal = document.getElementById('tapCheckoutModal');
  const frame = document.getElementById('tapCheckoutFrame');
  if (modal) modal.classList.remove('open');
  if (frame) frame.src = '';
}

async function initCliqPayments() {
  const container = document.getElementById('cliq-button-container');
  if (!container) return false;
  container.innerHTML = '<button class="btn-primary" style="width:100%;padding:12px;background:#2E7D32;margin-top:10px" onclick="startCliqCheckout()">💳 الدفع عبر Cliq</button>';
  return true;
}

async function startCliqCheckout() {
  if (!CU) {
    toast('يرجى تسجيل الدخول أولاً لإتمام الدفع', 'err');
    goPage('account');
    showAuth();
    return;
  }
  if (cart.length === 0) {
    toast('السلة فارغة', 'err');
    return;
  }

  try {
    const USD_TO_JOD_RATE = 0.71;
    // Calculate total amount from courses
    let totalAmount = 0;
    cart.forEach(courseId => {
      const course = COURSES.find(c => c.id === courseId);
      if (course) totalAmount += Number(course.price || 0);
    });

    // Show Cliq modal with bank details and amount
    const modal = document.getElementById('cliqCheckoutModal');
    const amountEl = document.getElementById('cliqAmount');
    if (modal) {
      if (amountEl) {
        // تحويل من الدولار الأمريكي إلى الدينار الأردني
        const jodAmount = (totalAmount * USD_TO_JOD_RATE).toFixed(2);
        amountEl.textContent = `${jodAmount} JOD`;
      }
      modal.classList.add('open');
    }

    // Make API request to create order record
    const { orderId, checkoutUrl, paymentAmount } = await apiRequest('/payments/create-cliq-charge', {
      method: 'POST',
      body: { courseIds: cart },
    });

    if (checkoutUrl) {
      window.location.href = checkoutUrl;
      return;
    }

    if (Number.isFinite(Number(paymentAmount)) && amountEl) {
      amountEl.textContent = `${Number(paymentAmount).toFixed(2)} JOD`;
    }

    toast(`تم إنشاء طلب الدفع. رقم الطلب: ${orderId}. سيُفعّل الاشتراك بعد تأكيد التحويل.`, 'gold');

  } catch (err) {
    closeCliqCheckoutModal();
    toast(err.message || 'حدث خطأ أثناء الدفع عبر كليك', 'err');
  }
}

function closeCliqCheckoutModal(){
  const modal = document.getElementById('cliqCheckoutModal');
  if (modal) modal.classList.remove('open');
}

function copyToClipboard(text, successMsg) {
  navigator.clipboard.writeText(text).then(() => {
    toast(successMsg, 'gold');
  }).catch(err => {
    console.error('Copy failed:', err);
    toast('فشل النسخ', 'err');
  });
}

function copyCliqAlias() {
  const aliasEl = document.getElementById('cliqAlias');
  if (aliasEl) copyToClipboard(aliasEl.textContent.trim(), 'تم نسخ الاسم المستعار ✓');
}

function copyCliqAmount() {
  const amountEl = document.getElementById('cliqAmount');
  if (amountEl) copyToClipboard(amountEl.textContent.replace(' JOD', '').trim(), 'تم نسخ المبلغ ✓');
}

function clearSession(){
  AUTH_TOKEN='';
  CU=null;
  localStorage.removeItem('hf_token');
  localStorage.removeItem('hf_user');
}

const USERNAME_REGEX=/^[\p{L}\p{N}_]{3,}$/u;
const PASSWORD_REGEX=/^(?=.*\p{L})(?=.*\p{N})(?=.*[^\p{L}\p{N}\s]).{6,}$/u;

function normalizeUsername(v){
  return String(v||'').trim().normalize('NFKC').toLowerCase();
}

function isValidUsername(v){
  return USERNAME_REGEX.test(normalizeUsername(v));
}

function isStrongPassword(v){
  return PASSWORD_REGEX.test(String(v||'').normalize('NFKC'));
}

function upsertCourseInState(course){
  const idx=COURSES.findIndex(x=>x.id===course.id);
  if(idx>=0) COURSES[idx]=course;
  else COURSES.push(course);
  COURSES.sort((a,b)=>a.id-b.id);
}

