async function sendDashboardMessage(){
  const recipientId=Number(CURRENT_MESSAGE_USER_ID);
  const body=document.getElementById('messageBody').value.trim();
  const imageFile=document.getElementById('messageImage').files[0];
  const button=document.getElementById('sendMessageButton');
  if(!recipientId||(!body&&!imageFile)){toast('اختر محادثة واكتب رسالة أو أرفق صورة','err');return;}
  button.disabled=true;
  button.classList.add('async-pending');
  try{
    const imageUrl=imageFile?await readFileAsDataURL(imageFile):'';
    if(imageUrl && imageUrl.length>5000000)throw new Error('حجم الصورة كبير جداً');
    await apiRequest('/messages',{method:'POST',body:{recipientId,body,imageUrl}});
    document.getElementById('messageBody').value='';
    document.getElementById('messageImage').value='';
    toast('تم إرسال الرسالة بنجاح','gold');
    await loadMessages();
    await loadNotifications();
  }catch(e){toast(e.message,'err');}
  finally{button.disabled=false;button.classList.remove('async-pending');}
}

