function readImageDimensions(dataUrl){
  return new Promise((resolve,reject)=>{
    const image=new Image();
    image.onload=()=>resolve({width:image.naturalWidth,height:image.naturalHeight});
    image.onerror=()=>reject(new Error('تعذر قراءة أبعاد الصورة'));
    image.src=dataUrl;
  });
}

async function loadAdminPosts(){
  const el=document.getElementById('adminPostsList');
  if(!el)return;
  try{
    const data=await apiRequest('/admin/posts');
    el.innerHTML=(data.posts||[]).map(post=>`<article style="padding:14px 0;border-top:1px solid var(--parchment)">
      <strong>${escapeHtml(post.title)}</strong> <small>${post.post_type==='announcement'?'إعلان هيدر':(post.course_title?escapeHtml(post.course_title):'منشور عام')}</small>
      <p style="margin:6px 0;color:var(--text3)">${escapeHtml(post.body)}</p>
      ${CU?.isAdmin?`<button class="btn-outline" onclick="editAdminPost(${post.id})">تعديل</button>
      <button class="btn-outline" style="color:#c0392b" onclick="deleteAdminPost(${post.id})">حذف</button>`:'<small>التعديل والحذف متاحان للمدير فقط</small>'}
    </article>`).join('')||'<div class="no-data">لا توجد منشورات</div>';
    window.ADMIN_POSTS=data.posts||[];
  }catch(e){el.innerHTML=`<div class="no-data">${escapeHtml(e.message)}</div>`;}
}

async function publishAdminPost(){
  const title=document.getElementById('postTitle').value.trim();
  const body=document.getElementById('postBody').value.trim();
  const courseId=Number(document.getElementById('postCourse').value)||null;
  const postType=document.getElementById('postType').value;
  if(!title||!body){toast('عنوان المنشور ومحتواه مطلوبان','err');return;}
  try{
    const imageFile=postType==='post'?document.getElementById('postImage')?.files?.[0]:null;
    const imageUrl=imageFile?await readFileAsDataURL(imageFile):'';
    if(imageUrl && imageUrl.length>5000000)throw new Error('حجم الصورة كبير جداً');
    if(imageUrl){
      const dimensions=await readImageDimensions(imageUrl);
      if(dimensions.width!==dimensions.height)throw new Error('يجب أن تكون صورة المنشور مربعة');
    }
    await apiRequest('/admin/posts',{method:'POST',body:{title,body,courseId,postType,imageUrl,isPublished:true}});
    document.getElementById('postTitle').value='';
    document.getElementById('postBody').value='';
    document.getElementById('postCourse').value='';
    document.getElementById('postImage').value='';
    document.getElementById('postImagePreview').style.display='none';
    toast('تم نشر المنشور بنجاح','gold');
    await loadAdminPosts();
  }catch(e){toast(e.message,'err');}
}

async function editAdminPost(id){
  const post=(window.ADMIN_POSTS||[]).find(item=>item.id===id);
  if(!post)return;
  const title=prompt('عنوان المنشور',post.title);
  if(title===null)return;
  const body=prompt('محتوى المنشور',post.body);
  if(body===null)return;
  try{
    await apiRequest(`/admin/posts/${id}`,{method:'PUT',body:{title,body,courseId:post.post_type==='announcement'?null:(post.course_id||null),postType:post.post_type||'post',isPublished:true}});
    await loadAdminPosts();
    toast('تم تحديث المنشور','gold');
  }catch(e){toast(e.message,'err');}
}

async function deleteAdminPost(id){
  if(!confirm('هل تريد حذف هذا المنشور؟'))return;
  try{
    await apiRequest(`/admin/posts/${id}`,{method:'DELETE'});
    await loadAdminPosts();
    toast('تم حذف المنشور','gold');
  }catch(e){toast(e.message,'err');}
}

