/* ═══════════ INIT ═══════════ */
async function init(){
  setLogos();
  const paymentParams=new URLSearchParams(window.location.search);
  const paymentStatus=paymentParams.get('payment');
  if(paymentStatus && ['success','tap-success','cliq-success'].includes(paymentStatus)){
    cart=[];
    localStorage.setItem('hf_cart','[]');
    updCartBadge();
    toast(paymentStatus==='cliq-success'
      ? 'تم إنشاء طلب الدفع عبر Cliq وسيتم تفعيل الاشتراك بعد تأكيد التحويل'
      : 'تم إكمال عملية الدفع؛ ستتم تحديث اشتراكاتك بعد تأكيد البوابــــة','gold');
    paymentParams.delete('payment');
    paymentParams.delete('session');
    paymentParams.delete('order');
    const cleanQuery=paymentParams.toString();
    history.replaceState({},document.title,`${window.location.pathname}${cleanQuery?'?'+cleanQuery:''}${window.location.hash}`);
  }
  try{
    await loadCourses();
  }catch(e){
    COURSES=[...DEFAULT_COURSES];
    toast('تعذر تحميل الكورسات من قاعدة البيانات، تم عرض البيانات الافتراضية مؤقتًا','err');
  }

  if(AUTH_TOKEN){
    try{
      const data=await apiRequest('/me');
      setSession(AUTH_TOKEN,data.user);
    }catch(e){
      clearSession();
    }
  }

  updCartBadge();
  updNav();
  renderHomeCoursesEl();
  loadHomepageStats();
  initTapPayments();
  await loadAnnouncements();
  await renderFooterCategories();
  if(CU&&document.getElementById('pg-account').classList.contains('active'))showDash();

  setTimeout(()=>{
    const l=document.getElementById('loader');
    l.classList.add('hide');
    setTimeout(()=>l.remove(),600);
  },1500);
}

async function loadAnnouncements(){
  const ticker=document.getElementById('announcementTicker');
  if(!ticker)return;
  try{
    const data=await apiRequest('/announcements');
    const items=data.announcements||[];
    if(!items.length){ticker.style.display='none';return;}
    ticker.style.display='block';
    const content=items.map(item=>escapeHtml(item.body)).join('  •  ');
    ticker.innerHTML=`<div class="announcement-stage"><span>${content}</span></div>`;
  }catch(error){ticker.style.display='none';}
}

init();
